def shortest_ug_brute(n, edges, src=0):
    g = [[] for _ in range(n)]
    for u, v in edges:
        g[u].append(v); g[v].append(u)
    best = [10**9] * n
    def dfs(u, d, seen):
        best[u] = min(best[u], d)
        for v in g[u]:
            if v not in seen:
                dfs(v, d + 1, seen | {v})
    dfs(src, 0, {src})
    return [-1 if x >= 10**9 else x for x in best]

from collections import defaultdict, deque

def shortest_ug_unit(n, edges, src=0):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    dist = [-1] * n
    dist[src] = 0
    q = deque([src])
    while q:
        u = q.popleft()
        for v in g[u]:
            if dist[v] < 0:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

