#include <bits/stdc++.h>
using namespace std;

vector<int> shortestUgUnit(int n, vector<pair<int,int>> edges, int src = 0) {
    vector<vector<int>> g(n);
    for (auto [u, v] : edges) {
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vector<int> dist(n, -1);
    queue<int> q;
    dist[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : g[u]) if (dist[v] < 0) {
            dist[v] = dist[u] + 1;
            q.push(v);
        }
    }
    return dist;
}
